package com.soulsync.config;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.time.*; import java.util.concurrent.*;
@Component
public class RateLimitFilter extends OncePerRequestFilter { private record Bucket(long minute,int count){} private final ConcurrentHashMap<String,Bucket> buckets=new ConcurrentHashMap<>();
 @Override protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();return !(p.equals("/api/v1/auth/login")||p.equals("/api/v1/auth/register")||p.equals("/api/v1/auth/forgot-password")||p.equals("/api/v1/auth/reset-password")||p.equals("/api/v1/auth/verify-email")||p.equals("/api/v1/auth/email-otp/resend")||p.equals("/api/v1/account/phone/request")||p.equals("/api/v1/account/phone/verify"));}
 @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{long minute=Instant.now().getEpochSecond()/60;String forwarded=r.getHeader("X-Forwarded-For");String ip=forwarded==null?r.getRemoteAddr():forwarded.split(",")[0].trim();String key=ip+"|"+r.getRequestURI();Bucket b=buckets.compute(key,(k,old)->old==null||old.minute()!=minute?new Bucket(minute,1):new Bucket(minute,old.count()+1));if(b.count()>12){s.setStatus(429);s.setContentType(MediaType.APPLICATION_JSON_VALUE);s.getWriter().write("{\"message\":\"Too many requests. Try again shortly.\"}");return;}c.doFilter(r,s);if(buckets.size()>10000)buckets.entrySet().removeIf(e->e.getValue().minute()<minute-5);}
}
